package com.sathavahana.kalamkari.controller;
import com.sathavahana.kalamkari.service.PaymentService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/payments") public class PaymentController {private final PaymentService payments; public PaymentController(PaymentService p){payments=p;} public record Webhook(String eventId,Long orderId,String status){} @PostMapping("/webhooks/{provider}") public Map<String,String> webhook(@PathVariable String provider,@RequestBody Webhook event){if(event.eventId()==null||event.orderId()==null)throw new IllegalArgumentException("eventId and orderId are required");var p=payments.capture(event.orderId());return Map.of("status","accepted","paymentStatus",p.getStatus());} @PostMapping("/{orderId}/refund") public Map<String,String> refund(@PathVariable Long orderId){return Map.of("status","refund_requested","orderId",orderId.toString());}}
